// PostgREST via n8n's HTTP node has shown up in this repo both as one item per row and as
// a single item whose .json IS the whole array (see ops/per-dealer-send/patch_channel.py's
// Resolve Send Channel nodes for the same defensive unwrap). Handle both shapes.
let rows = $input.all().map(i => i.json).filter(Boolean);
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
// Zero claimed = zero items out = this branch halts here, per the house fail-closed idiom
// already documented on nexus_resolve_channel_tenant() -- nothing further needs to run.
return rows.filter(Boolean).map(r => ({ json: r }));

const notif = $('Normalize Claimed Rows').item.json;
let rows = $input.all().map(i => i.json).filter(Boolean);
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
const first = rows[0] || {};

const base = {
  notification_id: notif.notification_id,
  sales_lead_id: notif.sales_lead_id,
  channel: notif.channel,
  reason_code: notif.reason,
  attempt_no: notif.attempt_no,
};

if (first && first.error !== undefined) {
  const msg = (first.error && (first.error.message || first.error.description)) || first.error;
  return [{ json: Object.assign({}, base, {
    sendable: false, error_code: 'LEAD_FETCH_FAILED', reason: String(msg).slice(0, 300),
  }) }];
}

const lead = Array.isArray(rows) ? rows[0] : null;
if (!lead) {
  return [{ json: Object.assign({}, base, {
    sendable: false, error_code: 'LEAD_NOT_FOUND',
    reason: 'nexus_sales_lead ' + notif.sales_lead_id + ' returned no row (on delete restrict '
      + 'should make this impossible while this outbox row exists).',
  }) }];
}
if (!lead.email) {
  return [{ json: Object.assign({}, base, {
    sendable: false, error_code: 'LEAD_HAS_NO_EMAIL',
    reason: 'channel EMAIL requires an email address and this lead has none on file '
      + '(phone ' + (lead.phone_e164 || 'also missing') + ').',
  }) }];
}

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const subject = 'NEXUS sales enquiry -- ' + lead.full_name
  + (lead.dealership ? ' (' + lead.dealership + ')' : '');
const html = '<p>A NEXUS sales enquiry has been queued for ' + esc(notif.attempt_no) + ' attempt(s).</p>'
  + '<table cellpadding=6 style="border-collapse:collapse">'
  + '<tr><td><b>Name</b></td><td>' + esc(lead.full_name) + '</td></tr>'
  + '<tr><td><b>Email</b></td><td>' + esc(lead.email) + '</td></tr>'
  + '<tr><td><b>Phone</b></td><td>' + esc(lead.phone_e164 || 'not given') + '</td></tr>'
  + '<tr><td><b>Dealership</b></td><td>' + esc(lead.dealership || 'not given') + '</td></tr>'
  + '<tr><td><b>Stock size</b></td><td>' + esc(lead.stock_size || 'not given') + '</td></tr>'
  + '<tr><td><b>Received</b></td><td>' + esc(lead.received_at) + '</td></tr>'
  + '</table><p>' + esc(lead.message || '(no message)') + '</p>'
  + '<p style="color:#888">notification_id ' + esc(notif.notification_id) + '</p>';

return [{ json: Object.assign({}, base, { sendable: true, subject, html }) }];

// Verifies the Gmail claim before anything writes it down -- same defect this guards
// against as Delivery Report in ops/site-enquiry/site-enquiry.workflow.json.
const item = $input.first().json || {};
const err = item.error;
let sent = true, why = null, messageId = null;
if (err !== undefined) {
  sent = false;
  why = String((err && (err.message || err.description)) || err).slice(0, 300);
} else if (!item.id && !item.threadId && !item.messageId) {
  sent = false;
  why = 'gmail node returned no message id';
} else {
  messageId = item.id || item.messageId || item.threadId;
}
const built = $('Build Email Content').item.json;
return [{ json: Object.assign({}, built, { sent, why, messageId }) }];
